package com.celik.kingdoms;

import java.util.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.Items;
import static com.celik.kingdoms.Rules.*;

/** Vanilla server-side menus; every destructive or vulnerability-changing action is reviewed. */
public final class DiplomacyUi {
    private static KingdomService s(){return KingdomsMod.service;}
    public static void alliances(ServerPlayer p){Ui.open(p,"alliances",m->{
        Kingdom k=s().requireOwn(p.getUUID());long pending=s().state.allianceRequests.stream().filter(r->r.expiresAt>s().now()&&(r.to.equals(k.id)||r.from.equals(k.id))).count();
        m.button(4,Items.IRON_CHAIN,"Kingdom alliances",List.of("Allies: "+k.allies.size()+" / "+s().config.maxAllies,"Both mayors must agree.",s().config.alliedFriendlyFire?"Allied PvP follows ordinary rules.":"PvP between allies is disabled.","Claim access still requires permission.","Alliances do not merge treasuries or claims."),null);
        m.button(20,Items.WRITABLE_BOOK,"Request alliance",List.of("Choose another kingdom.","A mayor must accept your request."),()->choose(p,false,0));
        m.button(22,Items.IRON_CHAIN,"Your allies",List.of("View allies and end alliances.","Changes freeze while either kingdom is at war."),()->allies(p,0));
        m.button(24,Items.PAPER,"Alliance requests",List.of("Pending: "+pending,"Review incoming requests or withdraw yours."),()->requests(p,0));
        m.button(30,Items.IRON_SWORD,"Joint wars",List.of("View both sides and the shared countdown.","Joining requires a mayor's approval."),()->war(p));
        m.button(32,Items.WRITABLE_BOOK,"War invitations",List.of("Review invitations from your allies.","Joining makes your claims vulnerable at war start.","Invitations expire when preparation ends."),()->warInvites(p,0));
        m.button(34,Items.BANNER.pick(net.minecraft.world.item.DyeColor.WHITE),"Recruit ally",List.of("Either side can recruit during preparation.","Allies must accept before wartime begins."),()->choose(p,true,0));m.back(p);
    },false);}
    public static void allies(ServerPlayer p,int page){Ui.open(p,"allied kingdoms",m->{Kingdom own=s().requireOwn(p.getUUID());List<Kingdom> all=s().diplomacy.allies(own);for(int i=page*36;i<Math.min(all.size(),page*36+36);i++){Kingdom k=all.get(i);m.button(i-page*36,KingdomIcons.stack(k),k.display(),List.of("Members: "+k.members.size(),"Claims: "+k.claims.size(),"Click to review ending this alliance."),()->Ui.confirm(p,"End alliance",List.of(k.display(),"Only a mayor can end the alliance.","Neither kingdom may be preparing or fighting a war."),()->s().diplomacy.remove(p,k.id)));}empty(m,all.size(),"No allies yet");m.pages(p,page,all.size(),q->allies(p,q));back(m,p);},false);}
    public static void choose(ServerPlayer p,boolean recruitment,int page){Ui.open(p,recruitment?"recruit allied kingdom":"request alliance",m->{Kingdom own=s().requireOwn(p.getUUID());List<Kingdom> all=new ArrayList<>(recruitment?s().diplomacy.allies(own):s().state.kingdoms.values().stream().filter(k->!k.id.equals(own.id)&&!own.allies.contains(k.id)).sorted(Comparator.comparing(Kingdom::display,String.CASE_INSENSITIVE_ORDER)).toList());for(int i=page*36;i<Math.min(all.size(),page*36+36);i++){Kingdom k=all.get(i);m.button(i-page*36,KingdomIcons.stack(k),k.display(),List.of("Members: "+k.members.size(),"Protection: "+Ui.time(k.protectedUntil-s().now()),"Cooldown: "+Ui.time(k.cooldownUntil-s().now()),recruitment?"Invite to your current war side.":"Send an alliance request to its mayors."),()->Ui.confirm(p,recruitment?"Invite ally to war":"Request alliance",List.of(k.display(),"A mayor of this kingdom must approve.",recruitment?"Must accept during preparation.":"Request expires after "+s().config.allianceRequestMinutes+" minutes."),()->{if(recruitment)s().diplomacy.inviteWar(p,k.id);else s().diplomacy.request(p,k.id);}));}empty(m,all.size(),recruitment?"No allied kingdoms available":"No kingdoms available");m.pages(p,page,all.size(),q->choose(p,recruitment,q));back(m,p);},false);}
    public static void requests(ServerPlayer p,int page){Ui.open(p,"alliance requests",m->{Kingdom own=s().requireOwn(p.getUUID());List<AllianceRequest> all=s().state.allianceRequests.stream().filter(r->r.expiresAt>s().now()&&(r.to.equals(own.id)||r.from.equals(own.id))).toList();for(int i=page*36;i<Math.min(all.size(),page*36+36);i++){AllianceRequest r=all.get(i);boolean incoming=r.to.equals(own.id);Kingdom k=s().state.kingdoms.get(incoming?r.from:r.to);m.button(i-page*36,KingdomIcons.stack(k),(incoming?"From ":"To ")+k.display(),List.of("Expires in: "+Ui.time(r.expiresAt-s().now()),incoming?"Review alliance request.":"Click to withdraw your request."),()->{if(incoming)reviewAlliance(p,k.id);else Ui.confirm(p,"Withdraw request",List.of(k.display()),()->s().diplomacy.cancel(p,k.id));});}empty(m,all.size(),"No pending requests");m.pages(p,page,all.size(),q->requests(p,q));back(m,p);},false);}
    private static void reviewAlliance(ServerPlayer p,UUID from){Ui.open(p,"review alliance",m->{Kingdom other=s().state.kingdoms.get(from);if(other==null){alliances(p);return;}m.button(13,KingdomIcons.stack(other),other.display(),List.of("Allied kingdoms retain their own land and treasury.","War participation always needs explicit approval.","Only a mayor may accept or decline."),null);m.button(29,Items.EMERALD_BLOCK,"Accept alliance",List.of(),()->{s().diplomacy.respond(p,from,true);alliances(p);});m.button(33,Items.REDSTONE_BLOCK,"Decline",List.of(),()->{s().diplomacy.respond(p,from,false);alliances(p);});back(m,p);},false);}
    public static void war(ServerPlayer p){Kingdom own=s().requireOwn(p.getUUID());War current=Rules.conflict(s().state,own.id,s().now());if(current==null){Ui.browse(p,0);return;}Ui.open(p,"joint war",m->{Kingdom k=s().requireOwn(p.getUUID());War w=Rules.conflict(s().state,k.id,s().now());if(w==null){Ui.home(p);return;}boolean attacking=w.side(true).contains(k.id);m.button(4,Items.CLOCK,w.preparing(s().now())?"War preparation":"Active war",List.of("Remaining: "+Ui.clock((w.preparing(s().now())?w.startedAt:w.endsAt)-s().now()),"Wartime duration: "+s().config.warMinutes+" minutes","All participants share this timer.","Logouts do not stop war."),null);m.button(20,Items.BANNER.pick(net.minecraft.world.item.DyeColor.WHITE),"Your side",List.of(s().diplomacy.names(w.side(attacking)),"Kingdoms: "+w.side(attacking).size()+" / "+s().config.maxKingdomsPerWarSide),null);m.button(24,Items.BANNER.pick(net.minecraft.world.item.DyeColor.RED),"Opposing side",List.of(s().diplomacy.names(w.side(!attacking)),"Claims open only between opposing sides.","Allies gain no automatic building permission."),null);if(w.preparing(s().now())&&s().config.jointWarsEnabled)m.button(40,Items.WRITABLE_BOOK,"Recruit an ally",List.of("Both sides may recruit during preparation.","Allied mayor must accept before war begins."),()->choose(p,true,0));m.button(42,Items.PAPER,"War invitations",List.of("Review invitations your kingdom has received."),()->warInvites(p,0));m.back(p);},false);}
    public static void declare(ServerPlayer p,UUID target){Ui.open(p,"declare war",m->{Kingdom other=s().state.kingdoms.get(target);s().require(other!=null,"That kingdom no longer exists.");m.button(13,KingdomIcons.stack(other),"War against "+other.display(),List.of("Preparation: "+s().config.warPreparationSeconds+" seconds","Claims stay protected during preparation.","Vulnerable wartime: "+s().config.warMinutes+" minutes","Membership and claim changes freeze.","Logouts do not stop war.","Invited allies must approve joining."),null);m.button(29,Items.IRON_SWORD,"Declare war",List.of("Start preparation for your kingdom.","You may recruit allies during preparation."),()->{s().declare(p,target);war(p);});if(s().config.jointWarsEnabled)m.button(31,Items.BANNER.pick(net.minecraft.world.item.DyeColor.WHITE),"Declare and invite allies",List.of("Start preparation and send your allies invitations.","Nobody joins without their mayor's approval."),()->{s().declare(p,target);s().diplomacy.recruitAll(p);war(p);});m.button(33,Items.REDSTONE_BLOCK,"Cancel",List.of(),()->Ui.home(p));},false);}
    public static void warInvites(ServerPlayer p,int page){Ui.open(p,"war invitations",m->{Kingdom own=s().requireOwn(p.getUUID());List<WarInvite> all=s().state.warInvites.stream().filter(i->i.to.equals(own.id)&&s().state.wars.stream().anyMatch(w->w.id.equals(i.war)&&w.preparing(s().now()))).toList();for(int index=page*36;index<Math.min(all.size(),page*36+36);index++){WarInvite i=all.get(index);War w=s().state.wars.stream().filter(q->q.id.equals(i.war)).findFirst().orElseThrow();Kingdom from=s().state.kingdoms.get(i.from);m.button(index-page*36,KingdomIcons.stack(from),"From "+from.display(),List.of("Join: "+s().diplomacy.names(w.side(i.attacking)),"Against: "+s().diplomacy.names(w.side(!i.attacking)),"Preparation remaining: "+Ui.clock(w.startedAt-s().now()),"Click to review joining this war."),()->reviewWar(p,i.war));}empty(m,all.size(),"No war invitations");m.pages(p,page,all.size(),q->warInvites(p,q));back(m,p);},false);}
    public static void reviewWar(ServerPlayer p,UUID war){Ui.open(p,"approve joint war",m->{Kingdom own=s().requireOwn(p.getUUID());WarInvite invite=s().state.warInvites.stream().filter(i->i.war.equals(war)&&i.to.equals(own.id)).findFirst().orElse(null);War w=s().state.wars.stream().filter(q->q.id.equals(war)&&q.preparing(s().now())).findFirst().orElse(null);if(invite==null||w==null){m.button(22,Items.BARRIER,"Invitation expired",List.of("Preparation has ended or the invite was removed."),null);back(m,p);return;}m.button(13,Items.IRON_SWORD,"Join this war?",List.of("Your side: "+s().diplomacy.names(w.side(invite.attacking)),"Enemies: "+s().diplomacy.names(w.side(!invite.attacking)),"Claims become vulnerable in "+Ui.clock(w.startedAt-s().now()),"Your membership and claims will freeze.","You cannot leave the war after accepting.","You receive the full war cooldown.","Only a mayor can approve."),null);m.button(29,Items.EMERALD_BLOCK,"Approve joining",List.of("I accept vulnerability against all opposing kingdoms."),()->{s().diplomacy.answerWar(p,war,true);DiplomacyUi.war(p);});m.button(33,Items.REDSTONE_BLOCK,"Decline",List.of(),()->{s().diplomacy.answerWar(p,war,false);alliances(p);});back(m,p);},false);}
    private static void empty(Ui.Menu m,int count,String label){if(count==0)m.button(22,Items.PAPER,label,List.of(),null);}
    private static void back(Ui.Menu m,ServerPlayer p){m.button(49,Items.ARROW,"Back",List.of(),()->alliances(p));}
    private DiplomacyUi(){}
}
